import assert from "node:assert/strict";
import { brotliDecompressSync } from "node:zlib";
import { test } from "vitest";
import { canonicalJson, sha256 } from "../src/canonical-json.js";
import { verifyKr065OpeningProposals,
  type Kr065OpeningVerificationInput } from "../src/kr065-opening-proposals.js";

// Generated by Python worker: two separate synthetic RD/KR sources. No project PDF.
const workerFixtureBrotliBase64 = "";
const workerResultHash = "7af4529613544f8b2ed90b576015efc9f7d252b14d9f6fb884b2c052898159cc";
const reviewHash = "d".repeat(64);

function workerJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(workerJson).join(",")}]`;
  if (value !== null && typeof value === "object") {
    const item = value as Record<string, unknown>;
    return `{${Object.keys(item).sort()
      .map((key) => `${JSON.stringify(key)}:${workerJson(item[key])}`).join(",")}}`;
  }
  return JSON.stringify(value);
}
function fixture(): Kr065OpeningVerificationInput {
  const f = JSON.parse(brotliDecompressSync(
    Buffer.from(workerFixtureBrotliBase64, "base64")).toString("utf8")) as any;
  return { objectId: f.objectId, inputManifestHash: f.inputManifestHash,
    sourceFiles: f.sources.map((source: any) => ({
      sourceFileId: source.sourceFileId, objectId: source.objectId,
      sha256: source.sha256, stages: source.stages,
      sourceReviewHash: reviewHash, sectionCode: source.sectionCode })),
    sourceReviews: Object.fromEntries(f.sources.map((source: any) => [source.sourceFileId,
      { sourceSha256: source.sha256, revisionStatus: source.revisionStatus,
        approvalStatus: source.approvalStatus, sectionCode: source.sectionCode,
        pageStages: source.pageStages, contentHash: reviewHash, decisionHash: reviewHash }])),
    textArtifacts: Object.fromEntries(f.textArtifacts.map((artifact: any) => [
      artifact.sourceFileId, { content_json: artifact,
        content_hash: sha256(canonicalJson(artifact)) }])),
    result: f.result };
}
function rehashResult(input: Kr065OpeningVerificationInput): void {
  const result = input.result as any;
  const { contentHash: _old, ...body } = result;
  result.contentHash = sha256(workerJson(body));
}

test("independently verifies Python KR-065 navigation with deferred OCR and limits", () => {
  const input = fixture();
  const result = input.result as any;
  assert.equal(result.contentHash, workerResultHash);
  assert.equal(verifyKr065OpeningProposals(input), true);
  const row = result.codeRows[0];
  assert.deepEqual([row.parameterCode, row.status, row.eligibleSourceCount,
    row.textCandidatePageCount, row.ocrRequiredPageCount, row.oversizeAnchorLineCount,
    row.duplicateAnchorCount, row.proposalCount, row.truncatedProposalCount,
    row.abstentionCount], ["KR-065", "ABSTAIN", 2, 2, 1, 1, 1, 20, 4, 2]);
  assert.deepEqual([row.absenceConclusion, result.findingCount, result.parameterCoverage],
    ["NOT_AVAILABLE", null, null]);
  assert.equal(row.proposals.find((p: any) =>
    p.proposalKind === "DESIGNED_CLOSURE_HEADING_NAVIGATION")?.unauthorizedFillStatus,
  "NOT_ESTABLISHED");
  assert.equal(row.proposals.every((p: any) => p.sameElementAssociation === "UNVERIFIED"), true);
});

test("rejects rehashed source swapping, forged number, contour and false-zero", () => {
  const changes: Array<(input: Kr065OpeningVerificationInput) => void> = [
    (input) => { (input.result as any).codeRows[0].proposals[2].sourceFileId = "F-KR-CLOSURE"; },
    (input) => { (input.result as any).codeRows[0].proposals[2].rawOpeningNumber = "99"; },
    (input) => { (input.result as any).codeRows[0].proposals[2].anchor.lineText = "отверстие №99"; },
    (input) => { (input.result as any).codeRows[0].proposals[2].anchor.bboxMilliPoints[1] += 1; },
    (input) => { (input.result as any).codeRows[0].proposals[2].drawingContourAssociation = "VERIFIED"; },
    (input) => { (input.result as any).codeRows[0].proposals[0].unauthorizedFillStatus = "CONFIRMED"; },
    (input) => { (input.result as any).codeRows[0].ocrRequiredPageCount = 0; },
    (input) => { (input.result as any).codeRows[0].truncatedProposalCount = 0; },
    (input) => { (input.result as any).codeRows[0].duplicateAnchorCount = 0; },
    (input) => { (input.result as any).codeRows[0].status = "PASS"; },
    (input) => { (input.result as any).findingCount = 1; },
  ];
  for (const [index, change] of changes.entries()) {
    const input = fixture(); change(input); rehashResult(input);
    assert.equal(verifyKr065OpeningProposals(input), false, `tamper ${index}`);
  }
});

test("rejects stale review, wrong role, OCR quality tamper and manifest swap", () => {
  const changes: Array<(input: Kr065OpeningVerificationInput) => void> = [
    (input) => { input.sourceReviews["F-KR-LEFT"].approvalStatus = "UNKNOWN"; },
    (input) => { input.sourceReviews["F-KR-LEFT"].contentHash = "e".repeat(64); },
    (input) => { input.sourceFiles[0].stages = ["PD"]; },
    (input) => { input.sourceFiles[0].sectionCode = "AR"; },
    (input) => { input.textArtifacts["F-KR-LEFT"].content_hash = "f".repeat(64); },
    (input) => { (input.textArtifacts["F-KR-LEFT"].content_json as any).pages[1].quality.disposition = "TEXT_LAYER_CANDIDATE"; },
    (input) => { input.inputManifestHash = "b".repeat(64); },
  ];
  for (const [index, change] of changes.entries()) {
    const input = fixture(); change(input);
    assert.equal(verifyKr065OpeningProposals(input), false, `scope ${index}`);
  }
});
